INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A microcirculação é o local onde ocorrem as trocas de substâncias entre o sangue e os tecidos. Qual o tipo de capilar, caracterizado por possuir pequenas aberturas no citoplasma endotelial, que é encontrado predominantemente nos glomérulos renais e glândulas endócrinas?","options":{"a":"Capilares contínuos.","b":"Capilares fenestrados.","c":"Capilares sinusoides (descontínuos).","d":"Arteríolas terminais.","e":"Vênulas pós-capilares."},"answer":"b","rationale":"Os capilares fenestrados possuem poros (fenestras) que facilitam a filtração e passagem de macromoléculas, sendo ideais para órgãos excretores e secretores.","option_rationales":{"a":"Errada. Comuns em músculos e pulmões, sem poros.","b":"Correta. Histologia e fisiologia vascular.","c":"Errada. Possuem grandes fendas, comuns no fígado e medula óssea.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Histologia"]}', '2b14ed85be90f1762061de4df4839adb', 25, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Veia Ázigo'' é uma estrutura de drenagem crucial. Qual a sua origem anatômica mais comum no abdome e qual o seu trajeto em relação ao diafragma?","options":{"a":"Origina-se da veia cava inferior; atravessa o hiato esofágico.","b":"Origina-se da união da veia lombar ascendente direita com a veia subcostal direita; atravessa o diafragma pelo hiato aórtico ou pilar direito.","c":"Origina-se da veia renal direita; atravessa o hiato da veia cava.","d":"Origina-se da veia porta; atravessa o pilar esquerdo.","e":"Origina-se do ducto torácico; não atravessa o diafragma."},"answer":"b","rationale":"A veia ázigo forma-se no nível de L1/L2 e sobe pelo lado direito da coluna vertebral.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia da drenagem venosa do tronco.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Tórax"]}', 'f0e077c295fd4404abe1ead9e776c5b6', 26, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"As ''Anastomoses Arteriovenosas'' são comunicações diretas que desviam o sangue dos capilares. Em qual destas regiões elas são particularmente abundantes para auxiliar na termorregulação?","options":{"a":"Cérebro.","b":"Pulmões.","c":"Pele das extremidades (dedos, orelhas, nariz).","d":"Músculo esquelético.","e":"Fígado."},"answer":"c","rationale":"Essas anastomoses (shunts) permitem que o sangue sangre calor rapidamente ou conserve-o ao desviar o fluxo dos plexos capilares superficiais.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Anatomia funcional e termorregulação.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Termorregulação"]}', '2c5716788e4e118b6a5aed7d28764f2d', 27, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Túnica Média'' das artérias elásticas, como a aorta, é caracterizada por qual componente predominante que permite a expansão e o recolhimento durante o ciclo cardíaco?","options":{"a":"Fibras musculares lisas em disposição longitudinal.","b":"Lâminas elásticas concêntricas (fenestradas).","c":"Tecido conjuntivo denso modelado.","d":"Vasa vasorum abundantes.","e":"Epitélio pavimentoso simples."},"answer":"b","rationale":"As artérias elásticas (de condução) possuem grande quantidade de elastina na túnica média para amortecer a pressão sistólica (efeito Windkessel).","option_rationales":{"a":"Errada. Disposição é circular.","b":"Correta. Histologia vascular.","c":"Errada.","d":"Errada. Estes ficam na túnica adventícia.","e":"Errada. Este é o endotélio (íntima)."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Histologia"]}', 'a7d58a1ef5e0c5d329294612272f9f4e', 28, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"Qual estrutura venosa situa-se no sulco entre os músculos deltoide e peitoral maior, sendo um ponto de acesso comum para cateterismos?","options":{"a":"Veia basílica.","b":"Veia cefálica.","c":"Veia braquial.","d":"Veia jugular externa.","e":"Veia subclávia."},"answer":"b","rationale":"A veia cefálica percorre o sulco deltopeitoral e perfura a fáscia clavi-peitoral para drenar na veia axilar.","option_rationales":{"a":"Errada. É medial.","b":"Correta. Anatomia de superfície e acesso vascular.","c":"Errada. É profunda.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Superior"]}', 'f91540b157fdc93a9364939ebb72c040', 29, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Veia Cava Inferior'' (VCI) recebe o sangue de diversas veias abdominais. Qual destas veias drena diretamente para a VCI no lado DIREITO, mas drena para a veia renal no lado ESQUERDO?","options":{"a":"Veia hepática.","b":"Veia gonadal (testicular ou ovariana).","c":"Veia mesentérica superior.","d":"Veia frênica inferior.","e":"Veia lombar ascendente."},"answer":"b","rationale":"Assimetria venosa clássica: a gonadal esquerda drena na renal esquerda em ângulo reto (relevância para varicocele).","option_rationales":{"a":"Errada. Todas drenam na VCI.","b":"Correta. Anatomia venosa abdominal comparada.","c":"Errada. Drena no sistema porta.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Abdome"]}', '71e50e2232079f52fd77d9103c149987', 30, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O ''Ducto Torácico'' transporta a maior parte da linfa do corpo. Onde ele desemboca no sistema venoso?","options":{"a":"Atrio direito.","b":"Junção das veias jugular interna e subclávia esquerdas (ângulo venoso de Pirogoff).","c":"Veia cava superior.","d":"Veia braquiocefálica direita.","e":"Junção das veias ilíacas."},"answer":"b","rationale":"O ducto torácico termina no lado esquerdo da base do pescoço.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia do sistema linfático.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Linfático"]}', '48c3cf89dfa0efa98ec36f426360f131', 31, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Femoral Profunda'' é o principal ramo da artéria femoral. Qual grupo de vasos ela emite para irrigar a musculatura posterior da coxa, perfurando o músculo adutor magno?","options":{"a":"Artérias circunflexas femorais.","b":"Artérias perfurantes.","c":"Artérias pudendas externas.","d":"Artéria descendente do joelho.","e":"Artérias surais."},"answer":"b","rationale":"As artérias perfurantes (geralmente quatro) contornam o fêmur para suprir os isquiotibiais.","option_rationales":{"a":"Errada. Irrigam a articulação do quadril e fêmur proximal.","b":"Correta. Vascularização da coxa.","c":"Errada.","d":"Errada.","e":"Errada. Ramos da poplítea."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Inferior"]}', 'e094f2408ffa6b231afe2b537b913f22', 32, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Barreira Hematoencefálica'' é uma especialização vascular crítica. Quais componentes celulares formam a base estrutural desta barreira nos capilares cerebrais?","options":{"a":"Células ependimárias e microglias.","b":"Células endoteliais com junções oclusivas (tight junctions) e prolongamentos de astrócitos (pés vasculares).","c":"Pericitos e neurônios piramidais.","d":"Plexo coroide.","e":"Lâmina muscular lisa espessa."},"answer":"b","rationale":"A barreira restringe a passagem de substâncias do sangue para o parênquima nervoso central.","option_rationales":{"a":"Errada.","b":"Correta. Neuroanatomia e histologia.","c":"Errada.","d":"Errada. Produz o líquor, não é a barreira capilar.","e":"Errada. Capilares não têm túnica muscular."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Neuroanatomia"]}', 'd46cdd33347692cbebef77213221130c', 33, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Circulação Coronária'' apresenta variações de dominância. O que define um coração como sendo de ''Dominância Direita''?","options":{"a":"A artéria coronária direita é mais calibrosa que a esquerda.","b":"A artéria interventricular posterior origina-se da artéria coronária direita.","c":"A artéria circunflexa irriga o nó sinoatrial.","d":"O ventrículo direito é maior que o esquerdo.","e":"A artéria marginal direita irriga o ápice cardíaco."},"answer":"b","rationale":"A dominância é definida pela origem da artéria interventricular posterior (IVP). Aproximadamente 70-85% das pessoas têm dominância direita.","option_rationales":{"a":"Errada. Calibre não define dominância.","b":"Correta. Anatomia cardíaca aplicada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Cardiologia"]}', '3a4e76d7c86267507d43cbf21880ec67', 34, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Mesentérica Inferior'' fornece ramos para o intestino grosso. Qual o nome da anastomose arterial que corre ao longo da borda interna do cólon, comunicando os ramos da mesentérica superior e inferior?","options":{"a":"Arco de Riolan (ou artéria marginal de Drummond).","b":"Plexo de Kiesselbach.","c":"Círculo de Willis.","d":"Arcada de Barkow.","e":"Artéria de Adamkiewicz."},"answer":"a","rationale":"A artéria marginal de Drummond garante fluxo colateral entre os territórios das mesentéricas.","option_rationales":{"a":"Correta. Vascularização intestinal e colaterais.","b":"Errada. Na cavidade nasal.","c":"Errada. No cérebro.","d":"Errada.","e":"Errada. No canal medular."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Abdome"]}', 'b4e483074d6dbbc55c0a8be6dbfa0e0b', 35, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"Na pelve feminina, qual a relação anatômica clássica e perigosa entre a ''Artéria Uterina'' e o ''Ureter''?","options":{"a":"O ureter passa superiormente à artéria uterina.","b":"O ureter passa inferiormente à artéria uterina (''água sob a ponte'').","c":"O ureter situa-se lateralmente à artéria em todo o trajeto.","d":"A artéria uterina é ramo da artéria mesentérica inferior.","e":"Eles não se cruzam."},"answer":"b","rationale":"Relação fundamental em histerectomias: a artéria uterina (vaso) cruza sobre o ureter (canal) próximo ao colo uterino.","option_rationales":{"a":"Errada. Oposto.","b":"Correta. Anatomia pélvica cirúrgica.","c":"Errada.","d":"Errada. Ramo da ilíaca interna.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Ginecologia"]}', '4544d36661830e8c8f3aa31177c31814', 36, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O ''Sistema Ázigo'' permite o retorno venoso se a veia cava inferior estiver obstruída. Qual veia drena o lado esquerdo superior do tórax e desemboca na veia ázigo no nível de T7/T8?","options":{"a":"Veia hemiázigo.","b":"Veia hemiázigo acessória.","c":"Veia subcostal esquerda.","d":"Veia intercostal superior esquerda.","e":"Veia lombar ascendente."},"answer":"b","rationale":"A hemiázigo acessória drena os espaços superiores esquerdos; a hemiázigo drena os inferiores.","option_rationales":{"a":"Errada. Drena a parte inferior esquerda.","b":"Correta. Anatomia venosa torácica.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Tórax"]}', '639983d3a668d0107ebac78759029efa', 37, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Poplítea'' divide-se na borda inferior do músculo poplíteo em quais dois ramos terminais?","options":{"a":"Artéria femoral e tibial.","b":"Artéria tibial anterior e tronco tibiofibular.","c":"Artéria tibial posterior e fibular.","d":"Artéria sural e genicular.","e":"Artéria pediosa e plantar."},"answer":"b","rationale":"A tibial anterior perfura a membrana interóssea para o compartimento anterior, enquanto o tronco tibiofibular continua póstero-inferiormente.","option_rationales":{"a":"Errada.","b":"Correta. Vascularização da perna.","c":"Errada. A fibular sai da tibial posterior.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Inferior"]}', '3c03c776048c75d6c5c7c51d2c54b4a1', 38, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Carótida Externa'' emite vários ramos. Qual deles fornece irrigação para as meninges, atravessando o forame espinhoso, e pode causar hematoma epidural em traumas?","options":{"a":"Artéria temporal superficial.","b":"Artéria meníngea média (ramo da maxilar).","c":"Artéria occipital.","d":"Artéria auricular posterior.","e":"Artéria faríngea ascendente."},"answer":"b","rationale":"A artéria meníngea média corre sob a região do ptério, ponto frágil do crânio.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia vascular clínica e trauma.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Neurocirurgia"]}', '1201edf334078213baacaf698997ac7b', 39, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O ''Pouso'' da artéria... perdão, ''Pulso''. O pulso da ''Artéria Pediosa'' (dorsal do pé) localiza-se em qual posição?","options":{"a":"Medial ao tendão do extensor longo do hálux.","b":"Lateral ao tendão do extensor longo do hálux.","c":"Posterior ao maléolo medial.","d":"Sob o maléolo lateral.","e":"No espaço entre o quarto e quinto metatarsos."},"answer":"b","rationale":"É a continuação da artéria tibial anterior no dorso do pé.","option_rationales":{"a":"Errada. Tendão situa-se medialmente à artéria.","b":"Correta. Exame físico vascular.","c":"Errada. Tibial posterior.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Exame Físico"]}', '79482a506c7eb7cf24f79c93e3f0f29c', 40, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Veia Renal Esquerda'' recebe tributárias que a veia renal direita geralmente não recebe. Além da veia gonadal esquerda, qual outra veia drena nela?","options":{"a":"Veia hepática média.","b":"Veia suprarrenal esquerda.","c":"Veia esplênica.","d":"Veia renal direita.","e":"Veia mesentérica inferior."},"answer":"b","rationale":"A suprarrenal esquerda drena na renal, enquanto a direita drena diretamente na VCI.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia venosa retroperitoneal.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Endocrinologia"]}', 'fc7fd80869ed315cbe021a14d7f38cc5', 41, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Sinusoide'' é um capilar altamente permeável. Qual característica histológica permite que células inteiras passem por sua parede no baço e medula óssea?","options":{"a":"Possuem fenestras com diafragma fino.","b":"Possuem grandes fendas intercelulares e membrana basal descontínua ou ausente.","c":"Têm endotélio contínuo e muitas vesículas de pinocitose.","d":"São envoltos por uma camada espessa de pericitos.","e":"Ficam localizados apenas no sistema nervoso central."},"answer":"b","rationale":"As sinusoides (ou capilares descontínuos) são adaptadas para o tráfego de células sanguíneas e proteínas grandes.","option_rationales":{"a":"Errada. Características de fenestrados.","b":"Correta. Histologia vascular.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Histologia"]}', '0d5470177e1afd06e6123ca65b92fc9c', 42, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Epigástrica Inferior'' é um ramo importante da artéria ilíaca externa. Qual a sua relação anatômica com o canal inguinal e a formação de hérnias diretas vs indiretas?","options":{"a":"Hérnias indiretas ocorrem mediais à artéria.","b":"Hérnias diretas ocorrem mediais à artéria (no triângulo de Hesselbach).","c":"A artéria corre dentro do funículo espermático.","d":"Hérnias femorais ocorrem superiores à artéria.","e":"A artéria situa-se posterior ao músculo psoas."},"answer":"b","rationale":"A artéria divide o espaço: lateral = indireta (pelo anel inguinal profundo); medial = direta (fraqueza da parede posterior).","option_rationales":{"a":"Errada. Ocorrem lateralmente.","b":"Correta. Anatomia aplicada à cirurgia.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Cirurgia"]}', '62c7d83cd9941d18377ca2d7593563cd', 43, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"O ''Sistema Linfático'' apresenta vasos com válvulas. Qual a principal função destas válvulas e como a linfa é propulsionada nos vasos maiores?","options":{"a":"Bombear ativamente a linfa; através de um coração linfático.","b":"Impedir o refluxo; através da contração de músculos esqueléticos adjacentes e da túnica média muscular.","c":"Filtrar resíduos; através dos linfonodos.","d":"Trocar oxigênio; através de poros nas válvulas.","e":"Assegurar fluxo bidirecional."},"answer":"b","rationale":"O sistema linfático é de baixa pressão e depende de forças externas e peristaltismo intrínseco.","option_rationales":{"a":"Errada. Humanos não têm corações linfáticos.","b":"Correta. Fisiologia e anatomia linfática.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Linfático"]}', 'f96d90cfc73d18bde061eb0bd86c8931', 44, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Veia Porta'' drena o trato digestório. Qual a sua relação anatômica com o ''Ducto Colédoco'' e a ''Artéria Hepática Própria'' no ligamento hepatoduodenal?","options":{"a":"A veia porta situa-se anteriormente a eles.","b":"A veia porta situa-se posteriormente a eles (no plano mais profundo).","c":"A veia porta situa-se à direita do colédoco.","d":"Eles não compartilham o mesmo ligamento.","e":"A artéria hepática é a estrutura mais posterior."},"answer":"b","rationale":"No pedículo hepático: Colédoco (frente, direita), Artéria (frente, esquerda), Veia Porta (atrás).","option_rationales":{"a":"Errada.","b":"Correta. Anatomia das vias biliares e sistema porta.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Gastro"]}', '05c791d475ebef6e9589185ccf7841ed', 45, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Artéria Meníngea Média'' é protegida pelo ptério. Qual o ramo original desta artéria e por qual orifício craniano ela entra?","options":{"a":"Ramo da facial; forame magno.","b":"Ramo da maxilar; forame espinhoso.","c":"Ramo da temporal superficial; forame oval.","d":"Ramo da carótida interna; canal carótico.","e":"Ramo da meníngea anterior; forame redondo."},"answer":"b","rationale":"É um ramo da primeira parte da artéria maxilar.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia do crânio e vascularização.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Cabeça"]}', 'a7040eced1ad206fba202a4197160b0e', 46, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Drenagem Venosa Profunda'' da perna segue as artérias. Quantas veias satélites (veias comitantes) geralmente acompanham cada artéria abaixo do joelho?","options":{"a":"Uma.","b":"Duas.","c":"Zero; as veias são apenas superficiais.","d":"Cinco.","e":"Três veias por artéria."},"answer":"b","rationale":"O sistema de veias comitantes ajuda no retorno venoso através da troca de calor e pulsação arterial.","option_rationales":{"a":"Errada. Comum em veias maiores como a femoral.","b":"Correta. Anatomia venosa profunda.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Membro Inferior"]}', 'cb1b112de61b0e72a38c5b62713eb474', 47, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"As ''Varizes Esofágicas'' são colaterais porto-sistêmicas. Qual o limite anatômico (fisiológico) que separa a drenagem para o sistema ázigo da drenagem para a veia porta no esôfago?","options":{"a":"Junção faringoesofágica.","b":"Transição entre o terço superior e médio.","c":"Cárdia (transição esofagogástrica).","d":"Nível da bifurcação da traqueia.","e":"Nível do hiato diafragmático."},"answer":"c","rationale":"É na região do cárdia que ocorre o shunt clínico mais importante.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Anatomia do sistema porta-sistêmico.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","HDA"]}', '7036722ca407f700ffae647e530aefbe', 48, 'draft'),
('a63743d8-0afb-4c36-a38d-aa1ebde1d498', '{"enunciado":"A ''Vasa Vasorum'' supre as paredes dos grandes vasos. Em qual túnica vascular eles são mais encontrados e por que artérias de médio calibre têm menos vasa vasorum que as grandes artérias?","options":{"a":"Túnica íntima; porque a íntima é mais espessa.","b":"Túnica adventícia; porque as paredes mais finas das artérias menores são nutridas por difusão do próprio lúmen.","c":"Túnica média; para fornecer oxigênio aos miócitos.","d":"Endotélio; para evitar coágulos.","e":"Em todas as camadas igualmente."},"answer":"b","rationale":"As grandes artérias (como a aorta) têm paredes tão espessas que a difusão do sangue luminal não atinge as camadas externas.","option_rationales":{"a":"Errada. Íntima é nutrida por difusão do lúmen.","b":"Correta. Histologia e fisiologia vascular.","c":"Errada. Eles penetram na média em grandes vasos, mas a origem é na adventícia.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Sistema Circulatório","Vasos Sanguíneos","Histologia"]}', 'fa98d4a1f0ddc2aafaf08a9e99ce3c7a', 49, 'draft');